# ============================================================
# 035_FiveMethod_BehaviouralProfiles_CORREGIDO.R
#
# Objective 4
# Behavioural profiles generated by the five operational
# classification methods and by the individual consensus analysis
#
# CORRECTED ANALYTICAL FOUNDATION
# - Stress only, n = 89
# - Traceability = Author + ID / Traceability_ID
# - Behavioural coordinates inherited unchanged from the
#   definitive Objective 3 Stress dataset:
#     distance_rz
#     crossing_rz
#     top_entry_rz
#     top_time_rz
# - Five classifications inherited from the definitive output
#   of Script 034. No classification is recalculated here.
# - Behavioural_Index is inherited unchanged from Script 034.
#
# IMPORTANT
# The previous script calculated Euclidean distance to (0,0,0,0)
# and called that point the control centroid. That is not valid for
# the corrected robust reference normalisation: zero is the
# Author-specific Control median on each variable, whereas the
# pooled Control atlas centroid is not necessarily the origin.
# That derived distance is therefore removed here and is NOT
# substituted by any newly invented metric.
#
# The behavioural comparisons in this script characterise the
# classes generated from the same behavioural data. They are not
# independent external validation tests.
# ============================================================

script_version <- paste(
  "035_FiveMethod_BehaviouralProfiles_CORREGIDO",
  "| 2026-08-10",
  "| corrected robust variables and Author + ID traceability"
)

cat("\nRunning: ", script_version, "\n", sep = "")

# ------------------------------------------------------------
# 0. Project root, packages, and output directories
# ------------------------------------------------------------

project_root <- "C:/Users/USER/Documents/LAPCOM_UCS_Resilience"

if (!dir.exists(project_root)) {
  stop(
    "Project root does not exist: ",
    project_root
  )
}

setwd(project_root)

required_packages <- c(
  "dplyr",
  "tidyr",
  "tibble",
  "ggplot2",
  "rstatix",
  "openxlsx"
)

missing_packages <- required_packages[
  !vapply(
    required_packages,
    requireNamespace,
    logical(1),
    quietly = TRUE
  )
]

if (length(missing_packages) > 0L) {
  stop(
    "Install the following packages before running this script:\n",
    paste(missing_packages, collapse = ", ")
  )
}

suppressPackageStartupMessages({
  library(dplyr)
  library(tidyr)
  library(tibble)
  library(ggplot2)
  library(rstatix)
  library(openxlsx)
})

expected_stress_n <- 89L
expected_authors <- c("1", "2", "3", "4")
numeric_tolerance <- 1e-10

methods <- c(
  "Swaminathan",
  "PCA_Quantiles",
  "GMM",
  "TwoStep",
  "Louvain"
)

allowed_labels <- c(
  "Susceptible",
  "Intermediate",
  "Resilient"
)

behaviour_variables <- c(
  "distance_rz",
  "crossing_rz",
  "top_entry_rz",
  "top_time_rz"
)

output_directories <- c(
  "03_Results/Figures",
  "03_Results/Tables",
  "03_Results/Objects"
)

for (directory_i in output_directories) {
  if (!dir.exists(directory_i)) {
    dir.create(
      directory_i,
      recursive = TRUE
    )
  }
}

objects_dir <- "03_Results/Objects"
tables_dir <- "03_Results/Tables"
figures_dir <- "03_Results/Figures"

# ------------------------------------------------------------
# 1. Corrected input objects
# ------------------------------------------------------------

method_file <- file.path(
  objects_dir,
  "objective4_five_method_classifications.rds"
)

behaviour_file <- file.path(
  "01_Data",
  "Processed",
  "objective3_stress_robust_z_control_reference.rds"
)

required_input_files <- c(
  method_file,
  behaviour_file
)

missing_input_files <- required_input_files[
  !file.exists(required_input_files)
]

if (length(missing_input_files) > 0L) {
  stop(
    "The following corrected input files were not found:\n",
    paste(missing_input_files, collapse = "\n")
  )
}

method_data <- readRDS(
  method_file
)

behaviour_source <- readRDS(
  behaviour_file
)

if (!is.data.frame(method_data)) {
  stop(
    basename(method_file),
    " does not contain a data frame."
  )
}

if (!is.data.frame(behaviour_source)) {
  stop(
    basename(behaviour_file),
    " does not contain a data frame."
  )
}

# ------------------------------------------------------------
# 2. Audit the five-method classification object
# ------------------------------------------------------------

required_method_columns <- c(
  "Author",
  "ID",
  "Traceability_ID",
  "Behavioural_Index",
  methods,
  "n_Resilient",
  "n_Susceptible",
  "n_Intermediate",
  "Resilience_Consensus_Score",
  "Susceptibility_Consensus_Score",
  "Intermediate_Consensus_Score",
  "Consensus_Category"
)

missing_method_columns <- setdiff(
  required_method_columns,
  names(method_data)
)

if (length(missing_method_columns) > 0L) {
  stop(
    "The five-method classification object is missing:\n",
    paste(missing_method_columns, collapse = ", ")
  )
}

method_data <- method_data %>%
  dplyr::mutate(
    Author = trimws(as.character(Author)),
    ID = trimws(as.character(ID)),
    Traceability_ID = trimws(as.character(Traceability_ID)),
    Behavioural_Index = as.numeric(Behavioural_Index)
  ) %>%
  dplyr::arrange(
    Traceability_ID
  )

if (nrow(method_data) != expected_stress_n) {
  stop(
    "Expected 89 fish in the five-method object; found ",
    nrow(method_data),
    "."
  )
}

if (
  anyDuplicated(method_data[c("Author", "ID")]) > 0L ||
  anyDuplicated(method_data$Traceability_ID) > 0L
) {
  stop(
    "Duplicated Author + ID traceability keys detected in method_data."
  )
}

if (
  !identical(
    sort(unique(method_data$Author)),
    expected_authors
  )
) {
  stop(
    "Expected Authors 1, 2, 3, and 4 in method_data."
  )
}

traceability_reconstructed <- paste(
  method_data$Author,
  method_data$ID,
  sep = " || "
)

if (
  !identical(
    method_data$Traceability_ID,
    traceability_reconstructed
  )
) {
  stop(
    "Traceability_ID does not exactly match Author + ID in method_data."
  )
}

if (
  any(
    !is.finite(
      method_data$Behavioural_Index
    )
  )
) {
  stop(
    "Missing or non-finite Behavioural_Index values detected."
  )
}

for (method_i in methods) {

  class_i <- trimws(
    as.character(
      method_data[[method_i]]
    )
  )

  if (anyNA(class_i)) {
    stop(
      "Missing classifications detected for ",
      method_i,
      "."
    )
  }

  invalid_i <- setdiff(
    unique(class_i),
    allowed_labels
  )

  if (length(invalid_i) > 0L) {
    stop(
      "Invalid labels detected for ",
      method_i,
      ": ",
      paste(invalid_i, collapse = ", ")
    )
  }

  method_data[[method_i]] <- class_i
}

# ------------------------------------------------------------
# 3. Prepare and audit definitive robust behavioural coordinates
# ------------------------------------------------------------

required_behaviour_columns <- c(
  "Author",
  "ID",
  "Traceability_ID",
  behaviour_variables
)

missing_behaviour_columns <- setdiff(
  required_behaviour_columns,
  names(behaviour_source)
)

if (length(missing_behaviour_columns) > 0L) {
  stop(
    "The definitive Objective 3 Stress object is missing:\n",
    paste(missing_behaviour_columns, collapse = ", ")
  )
}

behaviour_data <- behaviour_source %>%
  dplyr::transmute(
    Author = trimws(as.character(Author)),
    ID = trimws(as.character(ID)),
    Traceability_ID = trimws(as.character(Traceability_ID)),
    dplyr::across(
      dplyr::all_of(behaviour_variables),
      as.numeric
    )
  ) %>%
  dplyr::arrange(
    Traceability_ID
  )

if (nrow(behaviour_data) != expected_stress_n) {
  stop(
    "Expected 89 fish in the definitive Objective 3 Stress object; found ",
    nrow(behaviour_data),
    "."
  )
}

if (
  anyDuplicated(behaviour_data[c("Author", "ID")]) > 0L ||
  anyDuplicated(behaviour_data$Traceability_ID) > 0L
) {
  stop(
    "Duplicated Author + ID traceability keys detected in behaviour_data."
  )
}

if (
  !identical(
    method_data$Traceability_ID,
    behaviour_data$Traceability_ID
  )
) {
  stop(
    "The classification and behavioural objects do not contain exactly ",
    "the same 89 Stress fish."
  )
}

if (
  any(
    !is.finite(
      as.matrix(
        behaviour_data[
          behaviour_variables
        ]
      )
    )
  )
) {
  stop(
    "Missing or non-finite definitive robust behavioural values detected."
  )
}

# ------------------------------------------------------------
# 4. Merge classifications with definitive behavioural variables
# ------------------------------------------------------------

profile_data <- method_data %>%
  dplyr::left_join(
    behaviour_data,
    by = c(
      "Author",
      "ID",
      "Traceability_ID"
    )
  ) %>%
  dplyr::arrange(
    Traceability_ID
  )

if (nrow(profile_data) != expected_stress_n) {
  stop(
    "The integrated behavioural-profile dataset does not contain 89 fish."
  )
}

if (
  anyNA(
    profile_data[
      c(
        methods,
        behaviour_variables
      )
    ]
  )
) {
  stop(
    "Missing classifications or behavioural values detected after joining."
  )
}

# ------------------------------------------------------------
# 5. Long-format classifications
# ------------------------------------------------------------

method_profile_long <- profile_data %>%
  dplyr::select(
    Author,
    ID,
    Traceability_ID,
    Behavioural_Index,
    dplyr::all_of(methods),
    dplyr::all_of(behaviour_variables)
  ) %>%
  tidyr::pivot_longer(
    cols =
      dplyr::all_of(methods),

    names_to =
      "Method",

    values_to =
      "Classification"
  ) %>%
  dplyr::mutate(
    Method = factor(
      Method,
      levels = methods
    ),

    Classification = factor(
      Classification,
      levels = allowed_labels
    )
  )

# ------------------------------------------------------------
# 6. Long-format behavioural variables
# ------------------------------------------------------------

method_behaviour_long <- method_profile_long %>%
  tidyr::pivot_longer(
    cols =
      dplyr::all_of(
        behaviour_variables
      ),

    names_to =
      "Variable",

    values_to =
      "Value"
  ) %>%
  dplyr::mutate(
    Variable = factor(
      Variable,
      levels = behaviour_variables,
      labels = c(
        "Distance",
        "Line crossings",
        "Upper-zone entries",
        "Upper-zone time"
      )
    )
  )

# ------------------------------------------------------------
# 7. Descriptive statistics by method, class, and variable
# ------------------------------------------------------------

method_descriptive <- method_behaviour_long %>%
  dplyr::group_by(
    Method,
    Classification,
    Variable
  ) %>%
  dplyr::summarise(
    n = dplyr::n(),

    Mean =
      mean(
        Value,
        na.rm = TRUE
      ),

    SD =
      stats::sd(
        Value,
        na.rm = TRUE
      ),

    Median =
      stats::median(
        Value,
        na.rm = TRUE
      ),

    IQR =
      stats::IQR(
        Value,
        na.rm = TRUE
      ),

    Q1 =
      stats::quantile(
        Value,
        0.25,
        na.rm = TRUE
      ),

    Q3 =
      stats::quantile(
        Value,
        0.75,
        na.rm = TRUE
      ),

    Minimum =
      min(
        Value,
        na.rm = TRUE
      ),

    Maximum =
      max(
        Value,
        na.rm = TRUE
      ),

    .groups = "drop"
  )

# ------------------------------------------------------------
# 8. Behavioural centroids by method and class
# ------------------------------------------------------------

method_centroids <- method_profile_long %>%
  dplyr::group_by(
    Method,
    Classification
  ) %>%
  dplyr::summarise(
    n = dplyr::n(),

    distance_rz =
      mean(
        distance_rz,
        na.rm = TRUE
      ),

    crossing_rz =
      mean(
        crossing_rz,
        na.rm = TRUE
      ),

    top_entry_rz =
      mean(
        top_entry_rz,
        na.rm = TRUE
      ),

    top_time_rz =
      mean(
        top_time_rz,
        na.rm = TRUE
      ),

    Mean_Behavioural_Index =
      mean(
        Behavioural_Index,
        na.rm = TRUE
      ),

    .groups = "drop"
  )

# ------------------------------------------------------------
# 9. Behavioural_Index homogeneity by method and class
# ------------------------------------------------------------

method_index_summary <- method_profile_long %>%
  dplyr::group_by(
    Method,
    Classification
  ) %>%
  dplyr::summarise(
    n = dplyr::n(),

    Mean_Index =
      mean(
        Behavioural_Index,
        na.rm = TRUE
      ),

    SD_Index =
      stats::sd(
        Behavioural_Index,
        na.rm = TRUE
      ),

    Median_Index =
      stats::median(
        Behavioural_Index,
        na.rm = TRUE
      ),

    IQR_Index =
      stats::IQR(
        Behavioural_Index,
        na.rm = TRUE
      ),

    CV_Index_percent =
      dplyr::if_else(
        abs(Mean_Index) >
          numeric_tolerance,
        100 *
          SD_Index /
          abs(Mean_Index),
        NA_real_
      ),

    .groups = "drop"
  )

# ------------------------------------------------------------
# 10. Kruskal-Wallis tests by method and variable
# ------------------------------------------------------------

# These tests describe within-sample separation generated by each
# classifier. Because the same behavioural variables contribute to
# the classifications, they must not be interpreted as independent
# external validation.

kruskal_results <- method_behaviour_long %>%
  dplyr::group_by(
    Method,
    Variable
  ) %>%
  rstatix::kruskal_test(
    Value ~ Classification
  ) %>%
  dplyr::ungroup()

effect_size_results <- method_behaviour_long %>%
  dplyr::group_by(
    Method,
    Variable
  ) %>%
  rstatix::kruskal_effsize(
    Value ~ Classification
  ) %>%
  dplyr::ungroup()

# ------------------------------------------------------------
# 11. Dunn-Holm post hoc comparisons for three-class methods
# ------------------------------------------------------------

observed_class_counts <- method_profile_long %>%
  dplyr::filter(
    !is.na(Classification)
  ) %>%
  dplyr::distinct(
    Method,
    Classification
  ) %>%
  dplyr::count(
    Method,
    name = "n_classes"
  )

three_class_methods <- observed_class_counts %>%
  dplyr::filter(
    n_classes == 3L
  ) %>%
  dplyr::pull(
    Method
  ) %>%
  as.character()

dunn_results <- method_behaviour_long %>%
  dplyr::filter(
    as.character(Method) %in%
      three_class_methods
  ) %>%
  dplyr::group_by(
    Method,
    Variable
  ) %>%
  rstatix::dunn_test(
    Value ~ Classification,
    p.adjust.method = "holm"
  ) %>%
  dplyr::ungroup()

# ------------------------------------------------------------
# 12. Binary-method comparisons
# ------------------------------------------------------------

binary_methods <- observed_class_counts %>%
  dplyr::filter(
    n_classes == 2L
  ) %>%
  dplyr::pull(
    Method
  ) %>%
  as.character()

binary_wilcoxon_results <- method_behaviour_long %>%
  dplyr::filter(
    as.character(Method) %in%
      binary_methods
  ) %>%
  dplyr::group_by(
    Method,
    Variable
  ) %>%
  rstatix::wilcox_test(
    Value ~ Classification,
    exact = FALSE
  ) %>%
  dplyr::ungroup() %>%
  rstatix::adjust_pvalue(
    method = "holm"
  ) %>%
  rstatix::add_significance(
    p.col = "p.adj"
  )

binary_effect_results <- method_behaviour_long %>%
  dplyr::filter(
    as.character(Method) %in%
      binary_methods
  ) %>%
  dplyr::group_by(
    Method,
    Variable
  ) %>%
  rstatix::wilcox_effsize(
    Value ~ Classification
  ) %>%
  dplyr::ungroup()

# ------------------------------------------------------------
# 13. Consensus-category behavioural data
# ------------------------------------------------------------

consensus_behaviour_long <- profile_data %>%
  dplyr::select(
    Author,
    ID,
    Traceability_ID,
    Consensus_Category,
    Behavioural_Index,
    dplyr::all_of(
      behaviour_variables
    )
  ) %>%
  tidyr::pivot_longer(
    cols =
      dplyr::all_of(
        behaviour_variables
      ),

    names_to =
      "Variable",

    values_to =
      "Value"
  ) %>%
  dplyr::mutate(
    Variable = factor(
      Variable,
      levels = behaviour_variables,
      labels = c(
        "Distance",
        "Line crossings",
        "Upper-zone entries",
        "Upper-zone time"
      )
    )
  )

# ------------------------------------------------------------
# 14. Consensus-category descriptive statistics
# ------------------------------------------------------------

consensus_descriptive <- consensus_behaviour_long %>%
  dplyr::group_by(
    Consensus_Category,
    Variable
  ) %>%
  dplyr::summarise(
    n = dplyr::n(),

    Mean =
      mean(
        Value,
        na.rm = TRUE
      ),

    SD =
      stats::sd(
        Value,
        na.rm = TRUE
      ),

    Median =
      stats::median(
        Value,
        na.rm = TRUE
      ),

    IQR =
      stats::IQR(
        Value,
        na.rm = TRUE
      ),

    Minimum =
      min(
        Value,
        na.rm = TRUE
      ),

    Maximum =
      max(
        Value,
        na.rm = TRUE
      ),

    .groups = "drop"
  )

consensus_centroids <- profile_data %>%
  dplyr::group_by(
    Consensus_Category
  ) %>%
  dplyr::summarise(
    n = dplyr::n(),

    distance_rz =
      mean(
        distance_rz,
        na.rm = TRUE
      ),

    crossing_rz =
      mean(
        crossing_rz,
        na.rm = TRUE
      ),

    top_entry_rz =
      mean(
        top_entry_rz,
        na.rm = TRUE
      ),

    top_time_rz =
      mean(
        top_time_rz,
        na.rm = TRUE
      ),

    Mean_Behavioural_Index =
      mean(
        Behavioural_Index,
        na.rm = TRUE
      ),

    .groups = "drop"
  )

consensus_index_summary <- profile_data %>%
  dplyr::group_by(
    Consensus_Category
  ) %>%
  dplyr::summarise(
    n = dplyr::n(),

    Mean_Index =
      mean(
        Behavioural_Index,
        na.rm = TRUE
      ),

    SD_Index =
      stats::sd(
        Behavioural_Index,
        na.rm = TRUE
      ),

    Median_Index =
      stats::median(
        Behavioural_Index,
        na.rm = TRUE
      ),

    IQR_Index =
      stats::IQR(
        Behavioural_Index,
        na.rm = TRUE
      ),

    CV_Index_percent =
      dplyr::if_else(
        abs(Mean_Index) >
          numeric_tolerance,
        100 *
          SD_Index /
          abs(Mean_Index),
        NA_real_
      ),

    .groups = "drop"
  )

# ------------------------------------------------------------
# 15. Consensus-category Kruskal-Wallis analyses
# ------------------------------------------------------------

consensus_kruskal <- consensus_behaviour_long %>%
  dplyr::group_by(
    Variable
  ) %>%
  rstatix::kruskal_test(
    Value ~ Consensus_Category
  ) %>%
  dplyr::ungroup()

consensus_effect_size <- consensus_behaviour_long %>%
  dplyr::group_by(
    Variable
  ) %>%
  rstatix::kruskal_effsize(
    Value ~ Consensus_Category
  ) %>%
  dplyr::ungroup()

consensus_dunn <- consensus_behaviour_long %>%
  dplyr::group_by(
    Variable
  ) %>%
  rstatix::dunn_test(
    Value ~ Consensus_Category,
    p.adjust.method = "holm"
  ) %>%
  dplyr::ungroup()

# ------------------------------------------------------------
# 16. Behavioural-profile figure by method
# ------------------------------------------------------------

p_method_profiles <- ggplot2::ggplot(
  method_behaviour_long,
  ggplot2::aes(
    x = Classification,
    y = Value,
    fill = Classification
  )
) +
  ggplot2::geom_boxplot(
    outlier.shape = NA,
    width = 0.65
  ) +
  ggplot2::geom_jitter(
    width = 0.12,
    alpha = 0.45,
    size = 1.4
  ) +
  ggplot2::facet_grid(
    Variable ~ Method,
    scales = "free_y"
  ) +
  ggplot2::labs(
    x = NULL,
    y = "Control-referenced robust behavioural value",
    fill = NULL
  ) +
  ggplot2::theme_classic(
    base_size = 11,
    base_family = "Arial"
  ) +
  ggplot2::theme(
    legend.position = "top",

    axis.text.x =
      ggplot2::element_text(
        angle = 45,
        hjust = 1
      ),

    strip.background =
      ggplot2::element_blank(),

    strip.text =
      ggplot2::element_text(
        face = "bold"
      )
  )

print(
  p_method_profiles
)

method_profiles_pdf <- file.path(
  figures_dir,
  "Objective4_FiveMethod_BehaviouralProfiles.pdf"
)

method_profiles_tiff <- file.path(
  figures_dir,
  "Objective4_FiveMethod_BehaviouralProfiles.tiff"
)

ggplot2::ggsave(
  filename = method_profiles_pdf,
  plot = p_method_profiles,
  device = grDevices::cairo_pdf,
  width = 15,
  height = 10,
  units = "in",
  bg = "white"
)

ggplot2::ggsave(
  filename = method_profiles_tiff,
  plot = p_method_profiles,
  width = 15,
  height = 10,
  units = "in",
  dpi = 600,
  compression = "lzw",
  bg = "white"
)

# ------------------------------------------------------------
# 17. Behavioural-centroid figure
# ------------------------------------------------------------

centroid_long <- method_centroids %>%
  tidyr::pivot_longer(
    cols =
      dplyr::all_of(
        behaviour_variables
      ),

    names_to =
      "Variable",

    values_to =
      "Centroid"
  ) %>%
  dplyr::mutate(
    Variable = factor(
      Variable,
      levels = behaviour_variables,
      labels = c(
        "Distance",
        "Line crossings",
        "Upper-zone entries",
        "Upper-zone time"
      )
    )
  )

p_centroids <- ggplot2::ggplot(
  centroid_long,
  ggplot2::aes(
    x = Variable,
    y = Centroid,
    group = Classification,
    linetype = Classification,
    shape = Classification
  )
) +
  ggplot2::geom_hline(
    yintercept = 0,
    linetype = "dotted"
  ) +
  ggplot2::geom_line(
    linewidth = 0.8
  ) +
  ggplot2::geom_point(
    size = 2.7
  ) +
  ggplot2::facet_wrap(
    ~ Method,
    ncol = 3
  ) +
  ggplot2::labs(
    x = NULL,
    y = "Behavioural centroid (Control-referenced robust units)",
    linetype = NULL,
    shape = NULL
  ) +
  ggplot2::theme_classic(
    base_size = 12,
    base_family = "Arial"
  ) +
  ggplot2::theme(
    legend.position = "top",

    axis.text.x =
      ggplot2::element_text(
        angle = 35,
        hjust = 1
      )
  )

print(
  p_centroids
)

centroids_pdf <- file.path(
  figures_dir,
  "Objective4_FiveMethod_Centroids.pdf"
)

centroids_tiff <- file.path(
  figures_dir,
  "Objective4_FiveMethod_Centroids.tiff"
)

ggplot2::ggsave(
  filename = centroids_pdf,
  plot = p_centroids,
  device = grDevices::cairo_pdf,
  width = 11,
  height = 8,
  units = "in",
  bg = "white"
)

ggplot2::ggsave(
  filename = centroids_tiff,
  plot = p_centroids,
  width = 11,
  height = 8,
  units = "in",
  dpi = 600,
  compression = "lzw",
  bg = "white"
